{
  "nodes": {
    "Triggers": {
      "score": 1,
      "explanation": "The client identifies several cues that activate distress, including darkness, sounds, leaving the room, someone outside, and reminders that bring up the image.",
      "quote": "\"cant do the dark rn it makes everything feel too close and i keep jumping at every little sound\""
    },
    "Negative_Appraisals": {
      "score": 1,
      "explanation": "The client makes maladaptive interpretations about current safety and their ability to cope, such as expecting something bad to happen and being unable to stop it.",
      "quote": "\"i just feel like something bad is about to happen\""
    },
    "Memory": {
      "score": 1,
      "explanation": "There is explicit evidence of intrusive re-experiencing and reliving of the traumatic scene.",
      "quote": "[\"kept replaying it\", \"like im still stuck in that moment\", \"that scene flashes up like a picture\", \"im back there again\"]"
    },
    "Threat": {
      "score": 1,
      "explanation": "The client expresses a strong ongoing sense of danger and hypervigilance, including feeling on edge, bracing for harm, and staying ready for something bad.",
      "quote": "[\"now i just feel like something bad is about to happen\", \"i have to stay ready for something bad\", \"chest feels tight like im bracing for something bad even tho nothing is happening\", \"if i relax for one second something bad will happen\"]"
    },
    "Maladaptive_Strategies": {
      "score": 1,
      "explanation": "The client describes avoidance and safety behaviors, including staying away from dark, news clips, streets, people who look like them, and scanning/listening for danger.",
      "quote": "[\"i keep listening for every little sound and staring at the door\", \"i just try to stay away from anything that brings it up\", \"cant do dark or anything that brings that image back news clips streets even people who look like them it helps a bit if i stay away\"]"
    }
  },
  "edges": {
    "Triggers__Maladaptive_Strategies": {
      "score": 1,
      "explanation": "Triggers lead to avoidance and scanning behaviors.",
      "quote": "\"it helps a bit if i stay away\""
    },
    "Triggers__Threat": {
      "score": 1,
      "explanation": "External cues like darkness, sounds, and hearing someone outside increase the sense of danger and bodily arousal.",
      "quote": "[\"it makes everything feel too close and i keep jumping at every little sound\", \"it gets worse if i think about leaving the room or hear someone outside\"]"
    },
    "Triggers__Memory": {
      "score": 1,
      "explanation": "A sound cue triggered replaying and the scene flashing up.",
      "quote": "[\"heard a bang this morning and i froze then kept replaying it\", \"that scene flashes up like a picture\"]"
    },
    "Triggers__Negative_Appraisals": {
      "score": 1,
      "explanation": "Cues such as hearing a bang or being in the dark are linked to interpretations that something bad is about to happen or could happen again.",
      "quote": "[\"heard a bang this morning and i froze then kept replaying it and now i just feel like something bad is about to happen\", \"feels like it could happen again any second\"]"
    },
    "Negative_Appraisals__Maladaptive_Strategies": {
      "score": 1,
      "explanation": "Beliefs that relaxing will allow something bad to happen lead to staying alert and avoiding reminders.",
      "quote": "[\"like if i relax for one second something bad will happen\", \"so i just try to stay away from anything that brings it up\"]"
    },
    "Negative_Appraisals__Threat": {
      "score": 1,
      "explanation": "The appraisal that something bad will happen is directly tied to ongoing threat and bracing for harm.",
      "quote": "[\"something bad is about to happen\", \"i have to stay ready for something bad\"]"
    },
    "Negative_Appraisals__Memory": {
      "score": 1,
      "explanation": "The client links appraisals of ongoing danger with being back in the traumatic moment again.",
      "quote": "[\"feels like it could happen again any second and i wont be able to stop it like im still stuck in that moment\", \"im scared ill get caught off guard and freeze like im back there again\"]"
    },
    "Memory__Maladaptive_Strategies": {
      "score": 1,
      "explanation": "Intrusive imagery prompts avoidance of triggers and reminders.",
      "quote": "[\"that scene flashes up like a picture and then im back on edge so i just try to stay away from anything that brings it up\"]"
    },
    "Memory__Threat": {
      "score": 1,
      "explanation": "Reliving the scene is associated with being back on edge and anticipating danger.",
      "quote": "[\"that scene flashes up like a picture and then im back on edge\"]"
    },
    "Threat__Maladaptive_Strategies": {
      "score": 1,
      "explanation": "Feeling on edge and needing to stay ready leads to scanning, door-checking, and avoidance.",
      "quote": "[\"i have to stay ready for something bad\", \"i keep listening for every little sound and staring at the door\"]"
    }
  }
}
